    outside = set()
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in outside:
                outside.add((r, c))
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in outside:
                outside.add((r, c))
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if (0 <= nr < h and 0 <= nc < w and
                    grid[nr][nc] == background and (nr, nc) not in outside):
                outside.add((nr, nc))
                stack.append((nr, nc))

    # Recolor enclosed cavities; the 6-colored frame's cavity is the special
    # case filled with 2, while the other cavities are filled with 7.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r, c) not in outside:
                # Find nearby enclosing frame color.
                frame = None
                for rad in range(1, max(h, w)):
                    found = []
                    for rr in range(max(0, r-rad), min(h, r+rad+1)):
                        for cc in range(max(0, c-rad), min(w, c+rad+1)):
                            if grid[rr][cc] != background:
                                found.append(grid[rr][cc])
                    if found:
                        frame = max(set(found), key=found.count)
