def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = max(range(10), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            region = []
            touches_edge = False
            boundary_colors = set()

            while stack:
                x, y = stack.pop()
                region.append((x, y))
                if x == 0 or x == h - 1 or y == 0 or y == w - 1:
                    touches_edge = True
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if not (0 <= nx < h and 0 <= ny < w):
                        continue
                    if grid[nx][ny] == background:
                        if (nx, ny) not in seen:
                            seen.add((nx, ny))
                            stack.append((nx, ny))
                    else:
                        boundary_colors.add(grid[nx][ny])

            if not touches_edge and boundary_colors:
                fill = 2 if boundary_colors == {6} else 7
                for x, y in region:
                    out[x][y] = fill

    return out
